#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] mt-3" @click="retry(entry)" :disabled="!online || busy || syncing">Periksa / kirim ulang</button></div></template><p class="[padding:36px_18px] text-center [color:#75867b] [font-size:13px]" x-show="!queue.length">✓ Semua transaksi sudah tersinkron.</p><a class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] mt-4" href="{{ route('help') }}">Cara menangani antrean tertahan</a></section>
