<template x-if="modal==='qris' && payment"><section><h2>Scan untuk membayar</h2><p class="[font-size:clamp(24px,_3vw,_32px)] font-bold [letter-spacing:-0.04em] [margin:12px_0_7px] max-[701px]:[font-size:24px]" x-text="money(payment.grand_total)"></p><template x-if="payment.qr_url"><img :src="payment.qr_url" alt="Kode QRIS pembayaran" class="w-64 h-64 object-contain mx-auto"></template><p x-show="!payment.qr_url" class="[padding:13px_16px] rounded-md [background:#fff6df] [color:#81591c] [font-size:13px] [line-height:1.6]">Kode QR belum tersedia. Periksa status nota ini sebelum membuat pembayaran lain.</p><p class="[color:#65796f] [font-size:13px] [line-height:1.6] mt-3">Tunggu konfirmasi server. QR ini dapat dibuka kembali melalui tombol QRIS menunggu.</p><button class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] ![background:#17694d] !text-white ![border-color:#17694d] hover:![background:#12523d] w-full mt-4" @click="checkPayment()" :disabled="busy" x-text="busy?'Memeriksa…':'Periksa pembayaran'"></button></section></template>
<template x-if="modal==='receipt' && receipt"><section><span class="inline-block [padding:5px_10px] rounded-full [background:#edf5ee] [color:#356649] [font-size:11px] font-semibold">TERCATAT DI SERVER</span><h2 class="mt-3">Transaksi berhasil.</h2><p class="[font-size:clamp(24px,_3vw,_32px)] font-bold [letter-spacing:-0.04em] [margin:12px_0_7px] max-[701px]:[font-size:24px]" x-text="money(receipt.grand_total)"></p><p class="[color:#65796f] [font-size:13px] [line-height:1.6] break-all" x-text="receipt.invoice_number"></p><a class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] ![background:#17694d] !text-white ![border-color:#17694d] hover:![background:#12523d] w-full mt-5" :href="'/orders/'+receipt.order_id+'/print'" target="_blank" rel="noopener">Cetak struk ↗</a><button class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] w-full mt-2" @click="location.reload()">Pesanan berikutnya</button></section></template>
<section x-show="modal==='openShift'"><h2>Siap buka kedai?</h2><p class="[color:#65796f] [font-size:13px] [line-height:1.6] mt-2">Catat modal tunai yang ada di laci sebelum transaksi pertama.</p><form @submit.prevent="openShift()"><label class="block [font-size:12px] font-semibold [color:#536b5e] [&_input]:block [&_input]:w-full [&_input]:[margin-top:7px] [&_input]:[border:1px_solid_#dce5de] [&_input]:[border-radius:9px] [&_input]:[padding:11px] [&_input]:bg-white [&_input]:[font-size:14px] [&_input]:[color:#18372d] [&_input]:min-h-11 [&_select]:block [&_select]:w-full [&_select]:[margin-top:7px] [&_select]:[border:1px_solid_#dce5de] [&_select]:[border-radius:9px] [&_select]:[padding:11px] [&_select]:bg-white [&_select]:[font-size:14px] [&_select]:[color:#18372d] [&_select]:min-h-11 [&_textarea]:block [&_textarea]:w-full [&_textarea]:[margin-top:7px] [&_textarea]:[border:1px_solid_#dce5de] [&_textarea]:[border-radius:9px] [&_textarea]:[padding:11px] [&_textarea]:bg-white [&_textarea]:[font-size:14px] [&_textarea]:[color:#18372d] [&_textarea]:min-h-11 mt-5">Modal awal (Rp)<input type="number" x-model="shiftCash" min="0" required></label><button class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] ![background:#17694d] !text-white ![border-color:#17694d] hover:![background:#12523d] w-full mt-5" :disabled="busy">Buka shift</button></form></section>
<section x-show="modal==='closeShift'"><h2>Tutup shift</h2><p class="[color:#65796f] [font-size:13px] [line-height:1.6] mt-2">Pastikan antrean di perangkat lain juga sudah tersinkron.</p><p class="[color:#65796f] [font-size:13px] [line-height:1.6] mt-5">Kas yang diharapkan</p><p class="[font-size:clamp(24px,_3vw,_32px)] font-bold [letter-spacing:-0.04em] [margin:12px_0_7px] max-[701px]:[font-size:24px]" x-text="money(shiftSummary?.cash_expected)"></p><form @submit.prevent="closeShift()"><label class="block [font-size:12px] font-semibold [color:#536b5e] [&_input]:block [&_input]:w-full [&_input]:[margin-top:7px] [&_input]:[border:1px_solid_#dce5de] [&_input]:[border-radius:9px] [&_input]:[padding:11px] [&_input]:bg-white [&_input]:[font-size:14px] [&_input]:[color:#18372d] [&_input]:min-h-11 [&_select]:block [&_select]:w-full [&_select]:[margin-top:7px] [&_select]:[border:1px_solid_#dce5de] [&_select]:[border-radius:9px] [&_select]:[padding:11px] [&_select]:bg-white [&_select]:[font-size:14px] [&_select]:[color:#18372d] [&_select]:min-h-11 [&_textarea]:block [&_textarea]:w-full [&_textarea]:[margin-top:7px] [&_textarea]:[border:1px_solid_#dce5de] [&_textarea]:[border-radius:9px] [&_textarea]:[padding:11px] [&_textarea]:bg-white [&_textarea]:[font-size:14px] [&_textarea]:[color:#18372d] [&_textarea]:min-h-11">Uang fisik di laci (Rp)<input type="number" min="0" x-model="shiftCash" required></label><button class="inline-flex items-center justify-center gap-2 min-h-11 [padding:10px_17px] [border:1px_solid_#dae4dd] rounded-md bg-white [color:#234a3b] [font-size:13px] font-semibold cursor-pointer hover:[background:#f1f7f3] disabled:[opacity:0.45] disabled:cursor-wait focus-visible:[outline:3px_solid_#90b9a5] focus-visible:[outline-offset:3px] ![background:#17694d] !text-white ![border-color:#17694d] hover:![background:#12523d] w-full mt-5" :disabled="busy">Simpan & tutup shift</button></form></section>
</div></div>
</body></html>
